// Decides whether this sign-up needs a new client set up, and builds the new Google Sheet.
// Tab IDs match the master sheet, because Sara's call workflow finds some tabs by ID.
const inp = $('New Sign-up').first().json;
const existing = $input.all().map(function (i) { return i.json; }).filter(function (r) { return r && r.email; });
const email = String(inp.email || '').trim().toLowerCase();
const fullName = String(inp.full_name || '').trim();
const company = String(inp.company_name || '').trim() || fullName || 'New business';
const phone = String(inp.phone || '').trim();
if (!email || existing.length) return [{ json: { skip: true, email: email, company: company } }];

function cell(v) { return { userEnteredValue: { stringValue: String(v == null ? '' : v) } }; }
function tab(id, title, index, data) {
  return { properties: { sheetId: id, title: title, index: index, gridProperties: { frozenRowCount: 1 } },
    data: [{ startRow: 0, startColumn: 0, rowData: data.map(function (r) { return { values: r.map(cell) }; }) }] };
}
const spec = {
  properties: { title: 'Sara - ' + company + ' (client)', timeZone: 'America/New_York' },
  sheets: [
    tab(101, 'Business_Info', 0, [['Field', 'Value'], ['business_name', company], ['phone_number', phone], ['hours', 'To be confirmed'],
      ['timezone', 'America/New_York'], ['address', ''], ['services_offered', ''], ['booking_policy', ''], ['cancellation_policy', ''],
      ['escalation_phone', phone], ['escalation_email', email], ['greeting_script', 'Thanks for calling ' + company + ', this is Sara. How can I help you today?']]),
    tab(1057738413, 'Hours', 1, [['day', 'open', 'close'], ['Sunday', 'Closed', 'Closed'], ['Monday', '9:00', '17:00'], ['Tuesday', '9:00', '17:00'],
      ['Wednesday', '9:00', '17:00'], ['Thursday', '9:00', '17:00'], ['Friday', '9:00', '17:00'], ['Saturday', 'Closed', 'Closed']]),
    tab(713308780, 'Holiday', 2, [['date', 'name', 'closed_all_day', 'open', 'close']]),
    tab(102, 'FAQs', 3, [['question', 'answer']]),
    tab(772487488, 'Appointments', 4, [['id', 'customer_name', 'phone', 'service', 'datetime', 'status', 'notes', 'created_at', 'output', 'email']]),
    tab(814807539, 'Tickets', 5, [['id', 'customer_name', 'phone', 'issue', 'status', 'priority', 'created_at', 'notes', 'ticket_id', 'phone_number', 'issue_description']]),
    tab(808961940, 'Transfers', 6, [['timestamp', 'customer_name', 'caller_phone', 'department', 'reason', 'status']]),
    tab(1404738896, 'Call Backs', 7, [['timestamp', 'customer_name', 'caller_phone', 'callback_time', 'notes', 'status']]),
    tab(228614849, 'Call Logs', 8, [['call_id', 'caller_phone', 'duration_seconds', 'recording_url', 'timestamp', 'transcript']])
  ]
};
return [{ json: { skip: false, email: email, full_name: fullName, first_name: fullName.split(/\s+/)[0] || 'there', company: company, phone: phone, spec: spec } }];

parameters.message:
=A new business signed up and was set up automatically.

Business: {{ $('Plan Setup').first().json.company }}
Contact: {{ $('Plan Setup').first().json.full_name }}
Email: {{ $('Plan Setup').first().json.email }}
Phone: {{ $('Plan Setup').first().json.phone || 'not given' }}

Done for you:
- Their own Google Sheet: {{ $('Create Spreadsheet').first().json.spreadsheetUrl }}
- A new row in Client Config Master (status: setup, phone_number empty)
- A dashboard login for their email (Sara Portal Accounts table)
- A welcome email asking for their hours, services, FAQs and phone number

To make Sara answer their calls:
1. When they reply, fill in the Business_Info, Hours and FAQs tabs in their sheet.
2. Get or connect their phone number in Retell.
3. Put that number's digits in the phone_number cell of their Client Config Master row and change status to active.
4. Send their payment link.

