  { title: 'Call Backs', sheetId: 1404738896, index: 7 },
  { title: 'Call Logs', sheetId: 228614849, index: 8 }
].map(function (t) { return { json: t }; });

// What goes in each tab: Business_Info and Hours get starter rows, the rest get their column headers.
const p = $('Plan Setup').first().json;
function blank(cols) { const o = {}; cols.forEach(function (c) { o[c] = ''; }); return [o]; }
const info = [['business_name', p.company], ['phone_number', p.phone], ['hours', 'To be confirmed'], ['timezone', 'America/New_York'],
  ['address', ''], ['services_offered', ''], ['booking_policy', ''], ['cancellation_policy', ''], ['escalation_phone', p.phone],
  ['escalation_email', p.email], ['greeting_script', 'Thanks for calling ' + p.company + ', this is Sara. How can I help you today?']]
  .map(function (r) { return { Field: r[0], Value: r[1] }; });
const days = [['Sunday', 'Closed', 'Closed'], ['Monday', '9:00', '17:00'], ['Tuesday', '9:00', '17:00'], ['Wednesday', '9:00', '17:00'],
  ['Thursday', '9:00', '17:00'], ['Friday', '9:00', '17:00'], ['Saturday', 'Closed', 'Closed']]
  .map(function (r) { return { day: r[0], open: r[1], close: r[2] }; });
return [
  { tab: 'Business_Info', rows: info },
  { tab: 'Hours', rows: days },
  { tab: 'Holiday', rows: blank(['date', 'name', 'closed_all_day', 'open', 'close']) },
  { tab: 'FAQs', rows: blank(['question', 'answer']) },
  { tab: 'Appointments', rows: blank(['id', 'customer_name', 'phone', 'service', 'datetime', 'status', 'notes', 'created_at', 'output', 'email']) },
  { tab: 'Tickets', rows: blank(['id', 'customer_name', 'phone', 'issue', 'status', 'priority', 'created_at', 'notes', 'ticket_id', 'phone_number', 'issue_description']) },
  { tab: 'Transfers', rows: blank(['timestamp', 'customer_name', 'caller_phone', 'department', 'reason', 'status']) },
  { tab: 'Call Backs', rows: blank(['timestamp', 'customer_name', 'caller_phone', 'callback_time', 'notes', 'status']) },
  { tab: 'Call Logs', rows: blank(['call_id', 'caller_phone', 'duration_seconds', 'recording_url', 'timestamp', 'transcript']) }
].map(function (t) { return { json: t }; });

